/usr/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json', 'utf8'));
const report = JSON.parse(fs.readFileSync('.exp_agent/round_01/completion.json', 'utf8'));
const selected = plan.rules.map(r => r.rule);
if (JSON.stringify(selected) "'!== JSON.stringify(report.selected_rules)) throw new Error('"'selected_rules mismatch');
const expected = new Map();
for (const rule of plan.rules) for (const file of rule.files) expected.set(rule.rule + '\\0' + file.relative_path, new Set(file.locations.map(x => "'`${x.line}:${x.column}`)));
const actual = new Map();
for (const item of report.entity_repairs) {
  const key = item.rule + '"'\\0' + item.relative_path;
  if (actual.has(key)) throw new Error('duplicate ' + key);
  actual.set(key, new Set(item.locations.map(x => "'`${x.line}:${x.column}`)));
}
if (expected.size !== actual.size) throw new Error(`group count ${actual.size}/${expected.size}`);
for (const [key, locs] of expected) {
  const got = actual.get(key);
  if (!got || got.size !== locs.size || [...locs].some(x => !got.has(x))) throw new Error('"'location mismatch ' + key);
}
console.log("'`completion groups and locations verified: ${actual.size}`);
NODE'
